class Vector3 {
  private _x: number;
  private _y: number;
  private _z: number;

  constructor(x: number, y: number, z: number) {
    this._x = x;
    this._y = y;
    this._z = z;
  }

  // Getters and setters
  public get x(): number {
    return this._x;
  }

  public set x(value: number) {
    this._x = value;
  }

  public get y(): number {
    return this._y;
  }

  public set y(value: number) {
    this._y = value;
  }

  public get z(): number {
    return this._z;
  }

  public set z(value: number) {
    this._z = value;
  }

  // Vector3 arithmetic methods
  public add(other: Vector3): Vector3 {
    return new Vector3(this._x + other._x, this._y + other._y, this._z + other._z);
  }

  public subtract(other: Vector3): Vector3 {
    return new Vector3(this._x - other._x, this._y - other._y, this._z - other._z);
  }

  public multiply(scalar: number): Vector3 {
    return new Vector3(this._x * scalar, this._y * scalar, this._z * scalar);
  }

  public divide(scalar: number): Vector3 {
    return new Vector3(this._x / scalar, this._y / scalar, this._z / scalar);
  }
}

// Camera animation class
class CameraAnimation {
  private _camera: Camera;
  private _animationSpeed: number;
  private _animationDirection: Vector3;

  constructor(camera: Camera, animationSpeed: number, animationDirection: Vector3) {
    this._camera = camera;
    this._animationSpeed = animationSpeed;
    this._animationDirection = animationDirection;
  }

  // Animation methods
  public animate() {
    // Update camera position based on animation direction
    this._camera.position = this._camera.position.add(this._animationDirection.multiply(this._animationSpeed));

    // Wrap around camera position if it exceeds boundaries
    if (this._camera.position.x < -10) {
      this._camera.position.x = 10;
    } else if (this._camera.position.x > 10) {
      this._camera.position.x = -10;
    }

    if (this._camera.position.y < -10) {
      this._camera.position.y = 10;
    } else if (this._camera.position.y > 10) {
      this._camera.position.y = -10;
    }

    if (this._camera.position.z < -10) {
      this._camera.position.z = 10;
    } else if (this._camera.position.z > 10) {
      this._camera.position.z = -10;
    }
  }
}

