Query: given a list of transaction objects that contain coin name,datetime,profit earned/loss. write a function in dart that returns the top three coins with the highest average profit and the top 3 coins with highest average loss.

Response A: 

here's the dart code:

```dart
void main() {
  List<Transaction> transactions = [
    Transaction('bitcoin', DateTime.now(), 50.00),
    Transaction('ethereum', DateTime.now(), 75.00),
    Transaction('bitcoin', DateTime.now(), 40.00),
    Transaction('ethereum', DateTime.now(), 55.00),
    Transaction('bitcoin', DateTime.now(), 60.00),
  ];

  List<Transaction> getTopProfitCoins(List<Transaction> transactions, int count) {
    // calculate average profit for each coin
    Map<String, double> averageProfits = {};
    for (Transaction transaction in transactions) {
      String coinName = transaction.coinName;
      double profit = transaction.profitEarned;
      if (averageProfits.containsKey(coinName)) {
        averageProfits[coinName] += profit;
      } else {
        averageProfits[coinName] = profit;
      }
    }

    // sort average profits in descending order
    List<String> sortedCoins = averageProfits.entries.toList()
      ..sort((a, b) => b.value.compareTo(a.value));

    // return the top 3 coins
    return sortedCoins.sublist(0, count);
  }

  List<Transaction> getTopLossCoins(List<Transaction> transactions, int count) {
    // calculate average loss for each coin
    Map<String, double> averageLosses = {};
    for (Transaction transaction in transactions) {
      String coinName = transaction.coinName;
      double loss = transaction.profitEarned < 0 ? -transaction.profitEarned : 0;
      if (averageLosses.containsKey(coinName)) {
        averageLosses[coinName] += loss;
      } else {
        averageLosses[coinName] = loss;
      }
    }

    // sort average losses in ascending order
    List<String> sortedCoins = averageLosses.entries.toList()
      ..sort((a, b) => a.value.compareTo(b.value));

    // return the top 3 coins
    return sortedCoins.sublist(0, count);
  }

  List<Transaction> transactionsSortedByProfit = getTopProfitCoins(transactions, 3);
  List<Transaction> transactionsSortedByLoss = getTopLossCoins(transactions, 3);

  print('Top 3 coins with the highest average profit:');
  for (Transaction transaction in transactionsSortedByProfit) {
    print('${transaction.coinName}: ${transaction.profitEarned}');
  }

  print('\nTop 3 coins with the highest average loss:');
  for (Transaction transaction in transactionsSortedByLoss) {
    print('${transaction.coinName}: ${transaction.profitEarned}');
  }
}

class Transaction {
  String coinName;
  DateTime datetime;
  double profitEarned;

  Transaction(this.coinName, this.datetime, this.profitEarned);
}
```

