import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
public class EarthMagneticField {
    private String location;
    private double latitude;
    private double longitude;
    private double magneticFieldIntensity;
    public EarthMagneticField(String location, double latitude, double longitude, double magneticFieldIntensity) {
        this.location = location;
        this.latitude = latitude;
        this.longitude = longitude;
        this.magneticFieldIntensity = magneticFieldIntensity;
    }
    public String getLocation() {
        return location;
    }
    public double getLatitude() {
        return latitude;
    }
    public double getLongitude() {
        return longitude;
    }
    public double getMagneticFieldIntensity() {
        return magneticFieldIntensity;
    }
    public static void main(String[] args) {
        EarthMagneticField[] locations = {
            new EarthMagneticField("A", 20.5, 50.2, 0.22),
            new EarthMagneticField("B", 40.2, 60.7, 0.18),
            new EarthMagneticField("C", 10.1, 70.5, 0.25),
            new EarthMagneticField("D", 30.7, 80.1, 0.19),
            new EarthMagneticField("E", 50.6, 90.8, 0.21)
        };
        // Filter locations with magnetic field intensity greater than 0.2
        List<EarthMagneticField> filteredLocations = Arrays.stream(locations)
                .filter(l -> l.getMagneticFieldIntensity() > 0.2)
                .collect(Collectors.toList());
        // Calculate the average magnetic field intensity
        double averageMagneticFieldIntensity = filteredLocations.stream()
                .mapToDouble(l -> l.getMagneticFieldIntensity())
                .average()
                .getAsDouble();
        System.out.println("Average magnetic field intensity: " + averageMagneticFieldIntensity);
    }
}
