        if acceleration > otherCar.acceleration {
            comparison += "The \(model) has a higher acceleration than the \(otherCar.model)."
        } else if acceleration < otherCar.acceleration {
            comparison += "The \(model) has a lower acceleration than the \(otherCar.model)."
        } else {
            comparison += "The \(model) and the \(otherCar.model) have the same acceleration."
        }

        // Lap times comparison
        if lapTimes.first! < otherCar.lapTimes.first! {
            comparison += "The \(model) has a faster lap time than the \(otherCar.model) at the first track."
        } else if lapTimes.first! > otherCar.lapTimes.first! {
            comparison += "The \(model) has a slower lap time than the \(otherCar.model) at the first track."
        } else {
            comparison += "The \(model) and the \(otherCar.model) have the same lap time at the first track."
        }

        // Aerodynamic efficiency comparison
        if aerodynamicEfficiency > otherCar.aerodynamicEfficiency {
            comparison += "The \(model) has a higher aerodynamic efficiency than the \(otherCar.model)."
        } else if aerodynamicEfficiency < otherCar.aerodynamicEfficiency {
            comparison += "The \(model) has a lower aerodynamic efficiency than the \(otherCar.model)."
        } else {
            comparison += "The \(model) and the \(otherCar.model) have the same aerodynamic efficiency."
        }

        return comparison
    }
}
