```go
package main

import (
	"fmt"
	"os"
	"regexp"
	"strings"

	"github.com/apache/avro/v2/avro"
	"github.com/apache/avro/v2/codec/json"
	"github.com/apache/avro/v2/io"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: ./generate_avro_schema <go_source_file> <struct_name>")
		os.Exit(1)
	}

	goSourceFile := os.Args[1]
	structName := os.Args[2]

	file, err := os.Open(goSourceFile)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
	defer file.Close()

	scanner := regexp.MustCompile(`(?m)type (\w+) struct {`)
	scanner.Scan(file)

	if !scanner.Match() {
		fmt.Println("Unable to find struct definition in the Go source file.")
		os.Exit(1)
	}

	structDefinition := scanner.String()
	structDefinition = strings.TrimSpace(structDefinition)
	structDefinition = strings.TrimSuffix(structDefinition, "}")

	fields := extractFields(structDefinition)

	schema, err := avro.NewSchema(structName, fields)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	jsonEncoder := json.NewEncoder(os.Stdout)
	err = jsonEncoder.Encode(schema)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}

func extractFields(structDefinition string) []avro.Field {
	fields := []avro.Field{}

	scanner := regexp.MustCompile(`(?m)(\w+) (\w+)`)
	scanner.Scan(structDefinition)

	for scanner.Match() {
		fieldName := scanner.String()
		fieldType := scanner.String()

		fields = append(fields, avro.Field{
			Name:  fieldName,
			Type:  avro.NewSchema(fieldType),
		})

		scanner.Next()
	}

	return fields
}
