        }

        if typ == schema.File {
            continue
        }

        if typ == schema.Record {
            recordSchema := typ.(schema.RecordSchema)
            structName := recordSchema.Name()
            if structName != os.Args[2] {
                continue
            }

            fields := recordSchema.Fields()
            avroSchema := specific.NewSpecificRecord(fields)

            output, err := os.OpenFile(fmt.Sprintf("%s.avsc", structName), os.O_CREATE|os.O_WRONLY, 0644)
            if err != nil {
                log.Fatal(err)
            }
            defer output.Close()

            err = avroSchema.Write(output)
            if err != nil {
                log.Fatal(err)
            }
        }
    }
}

