```
import edu.stanford.nlp.pipeline.*;
import edu.stanford.nlp.ling.*;
import java.io.*;
import java.util.*;
public class ThemeExtraction {
    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("annotators", "tokenize, ssplit, pos, lemma, parse, sentiment");
        StanfordCoreNLP pipeline = new StanfordCoreNLP(props);
        List<String> articles = readArticles("news_corpus.txt");
        List<String> themes = new ArrayList<>();
        for (String article : articles) {
            Annotation annotation = new Annotation(article);
            pipeline.annotate(annotation);
            List<CoreLabel> tokens = annotation.get(CoreAnnotations.TokensAnnotation.class);
            for (CoreLabel token : tokens) {
                String word = token.get(CoreAnnotations.TextAnnotation.class);
                if (word.matches("^[a-zA-Z]+$")) {
                    themes.add(word);
                }
            }
        }
        Collections.sort(themes);
        System.out.println("Top 10 themes:");
        for (int i = 0; i < 10; i++) {
            System.out.println(themes.get(i));
        }
    }
    public static List<String> readArticles(String fileName) {
        List<String> articles = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(fileName))) {
            String line;
            while ((line = br.readLine()) != null) {
                articles.add(line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return articles;
    }
}
