```typescript
// Define the data interface
interface Data {
  name: string;
  value: number;
}

// Define the bar chart options interface
interface BarChartOptions {
  width: number;
  height: number;
  margin: { top: number; right: number; bottom: number; left: number };
  data: Data[];
  labels: string[];
}

// Define the bar chart function
function barChart(options: BarChartOptions): HTMLCanvasElement {
  // Set up the canvas
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  // Set the canvas dimensions
  canvas.width = options.width;
  canvas.height = options.height;

  // Set the margin
  const margin = options.margin;
  const width = canvas.width - margin.left - margin.right;
  const height = canvas.height - margin.top - margin.bottom;

  // Create the bar chart data
  const data = options.data;
  const labels = options.labels;

  // Create the bar chart
  const bars = [];
  for (let i = 0; i < data.length; i++) {
    const bar = {
      x: margin.left + i * (width / data.length),
      y: height - data[i].value,
      width: width / data.length,
      height: data[i].value,
    };
    bars.push(bar);
  }

  // Draw the bar chart
  ctx.beginPath();
  ctx.moveTo(margin.left, height);
  ctx.lineTo(margin.left, 0);
  ctx.lineTo(width + margin.right, 0);
  ctx.lineTo(width + margin.right, height);
  ctx.closePath();
  ctx.fillStyle = 'blue';
  ctx.fill();

  bars.forEach(bar => {
    ctx.beginPath();
    ctx.moveTo(bar.x, bar.y);
    ctx.lineTo(bar.x + bar.width, bar.y);
    ctx.lineTo(bar.x + bar.width, bar.y + bar.height);
    ctx.lineTo(bar.x, bar.y + bar.height);
    ctx.closePath();
    ctx.fillStyle = 'red';
    ctx.fill();
  });

  // Add the labels
  ctx.font = '12px Arial';
  ctx.fillStyle = 'black';
  labels.forEach((label, i) => {
    const x = margin.left + i * (width / data.length) + width / 2;
    const y = height + 10;
    ctx.fillText(label, x, y);
  });

  return canvas;
}

// Define the main function
function main() {
  const data = [
    { name: 'Pizza', value: 15 },
    { name: 'Burger', value: 20 },
    { name: 'Taco', value: 10 },
  ];
  const labels = ['Pizza', 'Burger', 'Taco'];
  const options = {
    width: 600,
    height: 400,
    margin: { top: 20, right: 20, bottom: 30, left: 40 },
    data: data,
    labels: labels,
  };
  const canvas = barChart(options);
  document.body.appendChild(canvas);
}

// Call the main function
main();
